// LIVE BUG FIX (2026-11, direct instruction) - "Generated by SUBH -
// Workforce Intelligence" and "Page X of Y" were both drawn 10pt PAST
// doc.page.maxY() (height - margins.bottom), and PDFKit's doc.text()
// (with an explicit `width`) always checks `document.y > maxY` before
// drawing - true here, so EVERY footer/page-number draw silently pushed a
// brand-new, otherwise-empty page (see pdfReport.js's own fix comment).
// A 1-page report became 3 pages (real content, a footer-only page, a
// page-number-only page); a 463-row/~20-page report gained 8-10 trailing
// blanks the same way.
//
// This check parses REAL rendered PDF buffers with pdfjs-dist (already a
// project dependency - no new one needed) and asserts, independent of
// pdfReport.js's own internal row-height math: every page has real report
// content (never ONLY footer/page-number text), every data row's unique
// marker appears exactly once across the whole document (nothing silently
// dropped), and the LAST page's "Page X of Y" has Y equal to the real
// page count pdfjs itself measured (this is exactly what the bug
// corrupted - Y used to undercount since bufferedPageRange() was read
// before the footer pass's own self-inflicted blank pages existed).
//
// Run manually: node scripts/check-pdf-report-pagination.js
// (not part of the default deterministic suites - needs pdfjs-dist's own
// parsing work, same class of "needs real work done" check as
// check-subh-panel-ui.js's real headless Chromium.)
const pdfReport = require('../src/pdfReport');
const tableExcelReport = require('../src/tableExcelReport');
const ExcelJS = require('exceljs');

const FOOTER_TEXT = 'Generated by SUBH - Workforce Intelligence';

let pass = 0, fail = 0;
const failures = [];
function check(label, ok, detail) {
  if (ok) { pass++; console.log('[ok] ' + label); }
  else { fail++; failures.push(label + (detail ? ' -- ' + detail : '')); console.log('[FAIL] ' + label + (detail ? ' -- ' + detail : '')); }
}

function markerRows(n, colCount) {
  return Array.from({ length: n }, (_, i) => {
    const marker = 'ROWMARK' + String(i + 1).padStart(5, '0');
    const row = [String(i + 1), marker];
    while (row.length < colCount) row.push('x');
    return row;
  });
}

// Builds a grouped Doer/HOD-shaped row set: N section headers, each
// followed by a handful of marker data rows - same {section}/plain-array
// shapes buildTablePdfBuffer already documents as its own row contract.
function groupedMarkerRows(sectionCount, rowsPerSection) {
  const rows = [];
  let n = 0;
  for (let s = 0; s < sectionCount; s++) {
    rows.push({ section: 'DOER: Person ' + (s + 1) });
    for (let r = 0; r < rowsPerSection; r++) {
      n++;
      rows.push([String(n), 'ROWMARK' + String(n).padStart(5, '0')]);
    }
  }
  return rows;
}

async function parsePdf(buf) {
  const pdfjsLib = await import('pdfjs-dist/legacy/build/pdf.mjs');
  // The "standardFontDataUrl" warning this prints is harmless - it only
  // affects font-metrics fallback for glyph width estimation, never the
  // getTextContent() string extraction these checks rely on.
  const loadingTask = pdfjsLib.getDocument({ data: new Uint8Array(buf) });
  const doc = await loadingTask.promise;
  const pages = [];
  for (let i = 1; i <= doc.numPages; i++) {
    const page = await doc.getPage(i);
    const content = await page.getTextContent();
    pages.push(content.items.map((it) => it.str).join(' '));
  }
  await doc.destroy();
  return { numPages: doc.numPages, pages };
}

// Strips the footer + "Page X of Y" text, then checks whether anything
// real is left - this IS the check "no page contains ONLY footer/page-
// number text", applied the same way to every page of every report shape.
function isBlankOrFooterOnly(pageText) {
  const stripped = pageText.replace(FOOTER_TEXT, '').replace(/Page\s+\d+\s+of\s+\d+/g, '').trim();
  return stripped.length === 0;
}

async function checkReportShape(label, rows, columns) {
  const buf = await pdfReport.buildTablePdfBuffer({
    title: label, subtitle: 'subtitle', columns, rows, landscape: false,
    footerText: FOOTER_TEXT, pageNumbers: true
  });
  const { numPages, pages } = await parsePdf(buf);

  check(label + ': produced at least 1 page', numPages >= 1, 'numPages=' + numPages);

  const blankPages = pages.map((t, i) => (isBlankOrFooterOnly(t) ? i + 1 : null)).filter((x) => x !== null);
  check(label + ': zero blank (footer/page-number-only) pages', blankPages.length === 0, 'blank page indices: ' + JSON.stringify(blankPages));

  // Every page carries its own footer text and its own "Page X of Y".
  const missingFooter = pages.map((t, i) => (t.includes(FOOTER_TEXT) ? null : i + 1)).filter((x) => x !== null);
  check(label + ': every page has its own footer text', missingFooter.length === 0, 'pages missing footer: ' + JSON.stringify(missingFooter));
  const pageNumMatches = pages.map((t) => t.match(/Page\s+(\d+)\s+of\s+(\d+)/));
  const missingPageNum = pageNumMatches.map((m, i) => (m ? null : i + 1)).filter((x) => x !== null);
  check(label + ': every page has its own "Page X of Y"', missingPageNum.length === 0, 'pages missing page number: ' + JSON.stringify(missingPageNum));

  // The real regression: Y used to undercount (read before the footer
  // pass's own self-inflicted blanks existed) - every page's Y must equal
  // the REAL page count pdfjs itself measured, and X must count up in
  // order with no gaps/repeats.
  const xs = pageNumMatches.map((m) => m && Number(m[1]));
  const ys = pageNumMatches.map((m) => m && Number(m[2]));
  check(label + ': every page\'s "Page X of Y" denominator equals the real page count', ys.every((y) => y === numPages), 'ys=' + JSON.stringify(ys) + ' numPages=' + numPages);
  check(label + ': "Page X of Y" numerators count up 1..N in order with no gaps/repeats', JSON.stringify(xs) === JSON.stringify(Array.from({ length: numPages }, (_, i) => i + 1)), 'xs=' + JSON.stringify(xs));

  // Completeness - every real data row's marker survives somewhere, and
  // nowhere else (never duplicated across a real+blank page pair, which is
  // exactly the old bug's own failure shape).
  const allText = pages.join('\n');
  const expectedMarkers = (rows || []).filter((r) => Array.isArray(r)).length;
  const foundMarkers = (allText.match(/ROWMARK\d{5}/g) || []);
  check(label + ': every data row\'s marker appears exactly once across the document (nothing dropped or duplicated)',
    foundMarkers.length === expectedMarkers && new Set(foundMarkers).size === expectedMarkers,
    'expected=' + expectedMarkers + ' found=' + foundMarkers.length + ' unique=' + new Set(foundMarkers).size);

  return { numPages, blankPages };
}

(async () => {
  // 1-page report - the exact historic failure mode (1 real page -> 3
  // pages: real, footer-only, page-number-only).
  await checkReportShape('1-page report', markerRows(3, 2), ['No', 'Marker']);

  // 45-row report - small enough to be ambiguous about "how many pages
  // SHOULD this need", so the assertions above (zero blank pages, correct
  // Y denominator, every marker present exactly once) are the real test,
  // not a hardcoded expected page count.
  const r45 = await checkReportShape('45-row report', markerRows(45, 2), ['No', 'Marker']);
  check('45-row report: spans more than 1 page (proves real multi-page pagination is actually exercised here, not just the 1-page case)', r45.numPages > 1, 'numPages=' + r45.numPages);

  // 463-row flat report (the large-report case from the live incident -
  // ~20 real pages, 8-10 trailing blanks before this fix).
  const r463 = await checkReportShape('463-row flat report', markerRows(463, 2), ['No', 'Marker']);
  check('463-row report: spans multiple pages', r463.numPages > 1, 'numPages=' + r463.numPages);

  // Grouped Doer/HOD report - same {section} row shape, a different code
  // path trigger (isSection) than the plain data rows above.
  const rGrouped = await checkReportShape('grouped Doer/HOD report', groupedMarkerRows(8, 15), ['No', 'Marker']);
  check('grouped Doer/HOD report: spans multiple pages', rGrouped.numPages > 1, 'numPages=' + rGrouped.numPages);
  // Section headers are real content too - confirm at least one survived
  // (proves the grouped-row code path itself, isSection, still renders
  // normally and wasn't touched by the footer-only fix).
  {
    const buf = await pdfReport.buildTablePdfBuffer({
      title: 'grouped Doer/HOD report', subtitle: 's', columns: ['No', 'Marker'],
      rows: groupedMarkerRows(8, 15), landscape: false, footerText: FOOTER_TEXT, pageNumbers: true
    });
    const { pages } = await parsePdf(buf);
    const allText = pages.join('\n');
    // Section headers render uppercased (see pdfReport.js's own
    // .toUpperCase() on the section bar text) - matched case-insensitively
    // since that's a deliberate display choice, not something this check
    // cares about.
    check('grouped Doer/HOD report: section headers (DOER: ...) render as real content', /DOER: Person 1\b/i.test(allText));
  }

  // Excel is a completely separate builder (tableExcelReport.js) that
  // never accepted footerText/pageNumbers in the first place - confirms
  // it's still fully unaffected by this PDF-only fix.
  {
    const rows = markerRows(45, 2);
    const xlsxBuf = await tableExcelReport.buildTableExcelBuffer({ title: 'Excel unaffected check', subtitle: 's', columns: ['No', 'Marker'], rows });
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(xlsxBuf);
    const sheet = wb.getWorksheet('Report');
    check('Excel export: still produces a valid workbook with a "Report" sheet', Boolean(sheet));
    const allCellText = [];
    sheet.eachRow((row) => row.eachCell((cell) => allCellText.push(String(cell.value))));
    const markersInXlsx = allCellText.filter((v) => /^ROWMARK\d{5}$/.test(v));
    check('Excel export: every data row\'s marker is present, unaffected by the PDF footer fix', markersInXlsx.length === rows.length, 'expected=' + rows.length + ' found=' + markersInXlsx.length);
  }

  console.log('======================================================================');
  console.log(pass + '/' + (pass + fail) + ' passed');
  if (fail > 0) {
    console.log('FAILURES:');
    failures.forEach((f) => console.log('  - ' + f));
    process.exit(1);
  }
})().catch((err) => { console.error(err); process.exit(1); });
